CREATE TABLE employees (
  employee_id INT,
  name VARCHAR(255),
  manager_id INT
);

SELECT e1.name AS employee, e2.name AS manager
FROM employees e1
JOIN employees e2 ON e1.manager_id = e2.employee_id;

CREATE TABLE employees (
  id INT,
  name VARCHAR(255),
  salary DECIMAL(10, 2)
);
